def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'

    opp_d = sum(1 for a, b in history if b == 'D')
    my_d = sum(1 for a, b in history if a == 'D')

    if n >= 99:
        return 'D'
    if n >= 96 and opp_d <= 2:
        if rng.random() < 0.5:
            return 'D'

    dd = dc = cd = cc = 0
    for i in range(1, n):
        my_prev = history[i-1][0]
        opp_cur = history[i][1]
        if my_prev == 'D':
            if opp_cur == 'D':
                dd += 1
            else:
                dc += 1
        else:
            if opp_cur == 'D':
                cd += 1
            else:
                cc += 1

    retaliatory = False
    if dd + dc > 0 and cd + cc > 0:
        p_d_after_d = dd / (dd + dc)
        p_d_after_c = cd / (cd + cc)
        if p_d_after_d > p_d_after_c + 0.15:
            retaliatory = True

    if retaliatory:
        return 'C'

    if opp_d > 0.6 * n:
        return 'D'

    if my_d == 0:
        if n < 4:
            return 'C'
        if n == 4:
            return 'D'
        if n == 5:
            return 'C'

    if rng.random() < 0.8:
        return 'D'
    return 'C'
